  join operations o on o.client_key = md5(t.key)::uuid and o.business_id = t.id
  join reviews r on r.operation_id = o.id and r.status <> 'removed'
 where r.user_id <> (select u.id from users u where u.phone = t.u)
   and not exists (select 1 from review_helpful h where h.review_id = r.id and h.user_id = (select u.id from users u where u.phone = t.u));
update reviews r set helpful_count = (select count(*) from review_helpful h where h.review_id = r.id)
 where r.business_id = any(array['bufete-almonte-y-asociados-hazleton','oficina-legal-cabrera-inmigracion-allentown','abogada-mercedes-valdez-wilkes-barre','centro-legal-familia-unida-scranton','ferreira-immigration-law-reading','oficina-juridica-santana-hazleton','bufete-hernandez-inmigracion-allentown','abogado-rafael-pena-y-equipo-wilkes-barre','defensa-migratoria-del-valle-scranton','bufete-ramirez-y-colon-reading','ayuda-migratoria-la-puerta-abierta-allentown','centro-de-documentos-nuevo-camino-wilkes-barre','servicios-migratorios-esperanza-scranton','tramites-y-papeles-don-luis-reading','asistencia-de-inmigracion-mano-amiga-hazleton','centro-de-ayuda-migratoria-nuestra-tierra-allentown','documentos-al-dia-wilkes-barre','servicios-de-inmigracion-puente-seguro-scranton','papeles-en-orden-latino-reading','ayuda-de-inmigracion-santa-maria-hazleton','tramites-consulares-la-patria-wilkes-barre','gestoria-pasaporte-rapido-scranton','notaria-y-consulado-hermanos-pena-reading','apostillas-y-tramites-del-cibao-hazleton','documentos-consulares-quisqueya-allentown','gestoria-latina-de-documentos-wilkes-barre','notaria-publica-la-esquina-scranton','tramites-consulares-tierra-querida-reading','servicios-consulares-y-notaria-colon-hazleton','pasaportes-y-poderes-mi-raiz-allentown','oficina-legal-valdez-y-nunez-scranton','bufete-juridico-colon-reading','abogado-carlos-medina-hazleton','asesoria-legal-del-pueblo-allentown','firma-legal-dominguez-wilkes-barre','bufete-de-familia-baez-scranton','abogada-laura-paulino-y-asociados-reading','oficina-de-abogados-tavarez-hazleton','bufete-jimenez-y-cruz-allentown','despacho-legal-santa-rosa-wilkes-barre','abogada-de-familia-altagracia-reyes-reading','bufete-familiar-luz-y-derecho-hazleton','oficina-de-derecho-familiar-soto-allentown','centro-legal-de-la-familia-latina-wilkes-barre','firma-familiar-torres-y-medina-scranton','defensa-de-la-familia-colon-reading','abogados-de-familia-del-valle-hazleton','derecho-familiar-dominguez-allen