insert into business_posts (business_id, city_id, kind, title, body, link_kind, item_id, price_was_cents, price_now_cents, aviso, poll, audience, publish_at, ends_at, status, pinned, created_by, created_at)
select t.id, t.city, t.kind, t.title, t.body, case when t.it is null then 'none' else 'item' end,
       (select i.id from items i where i.business_id = t.id and i.module = 'svc' and i.sort = t.it), t.was, t.now_, t.aviso, t.poll, 'all', (t.at::timestamp at time zone 'America/New_York'), case when t.ends is not null then (t.ends::timestamp at time zone 'America/New_York') end,
